import{_ as e,o as r,c as d,a1 as a}from"./chunks/framework.DdbKPUhY.js";const m=JSON.parse('{"title":"Performance Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/performance.md","filePath":"spec/performance.md"}'),o={name:"spec/performance.md"};function n(s,t,i,l,c,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="performance-spec" tabindex="-1">Performance Spec <a class="header-anchor" href="#performance-spec" aria-label="Permalink to &quot;Performance Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This spec defines the performance benchmarks, throughput targets, latency budgets, and resource limits that UVHTTP must satisfy. All measurements are taken on the reference benchmark host.</p><h2 id="reference-benchmark-host" tabindex="-1">Reference Benchmark Host <a class="header-anchor" href="#reference-benchmark-host" aria-label="Permalink to &quot;Reference Benchmark Host&quot;">​</a></h2><ul><li><strong>CPU</strong>: AMD Ryzen 7 5800H, 12 cores</li><li><strong>OS</strong>: Linux 6.17.13-2-pve</li><li><strong>Compiler</strong>: GCC 11.4.0 Release build (<code>-O2 -DNDEBUG</code>)</li><li><strong>Allocator</strong>: System allocator</li><li><strong>Test tool</strong>: wrk 4.1.0</li><li><strong>Test duration</strong>: 10 seconds per run</li><li><strong>Server</strong>: built-in <code>test_performance_e2e</code></li></ul><h2 id="throughput-requirements" tabindex="-1">Throughput Requirements <a class="header-anchor" href="#throughput-requirements" aria-label="Permalink to &quot;Throughput Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Connections</th><th>Min RPS</th><th>Target RPS</th><th>Notes</th></tr></thead><tbody><tr><td>Low concurrency</td><td>10</td><td>18,000</td><td>19,887</td><td>P50 &lt; 0.5ms</td></tr><tr><td>Medium concurrency</td><td>100</td><td>18,000</td><td>19,834</td><td>Flat vs low</td></tr><tr><td>High concurrency</td><td>500</td><td>18,000</td><td>19,810</td><td>Flat vs 100</td></tr><tr><td>Extreme concurrency</td><td>1000</td><td>16,000</td><td>18,518</td><td>Graceful degradation</td></tr><tr><td>JSON endpoint</td><td>100</td><td>17,000</td><td>19,451</td><td></td></tr><tr><td>Large response 1KB</td><td>100</td><td>17,000</td><td>19,524</td><td></td></tr><tr><td><strong>Socket errors</strong></td><td><strong>All</strong></td><td><strong>0</strong></td><td><strong>0</strong></td><td>Zero tolerance</td></tr></tbody></table><h2 id="latency-requirements" tabindex="-1">Latency Requirements <a class="header-anchor" href="#latency-requirements" aria-label="Permalink to &quot;Latency Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Percentile</th><th>Latency Budget</th></tr></thead><tbody><tr><td>P50</td><td>&lt; 5ms</td></tr><tr><td>P90</td><td>&lt; 10ms</td></tr><tr><td>P95</td><td>&lt; 15ms</td></tr><tr><td>P99</td><td>&lt; 25ms</td></tr></tbody></table><h2 id="memory-requirements" tabindex="-1">Memory Requirements <a class="header-anchor" href="#memory-requirements" aria-label="Permalink to &quot;Memory Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Budget</th><th>Notes</th></tr></thead><tbody><tr><td>Static library size</td><td>&lt; 300 KB</td><td>Stripped Release build</td></tr><tr><td>Per-server instance</td><td>&lt; 512 bytes</td><td>Plus per-connection allocations</td></tr><tr><td>Per-connection</td><td>&lt; 4 KB</td><td>Request + response + buffers</td></tr><tr><td>Steady-state RSS</td><td>Flat</td><td>No growth under sustained load</td></tr><tr><td>Cold start</td><td>&lt; 500ms</td><td>First byte after launch</td></tr></tbody></table><h2 id="long-run-stability" tabindex="-1">Long-Run Stability <a class="header-anchor" href="#long-run-stability" aria-label="Permalink to &quot;Long-Run Stability&quot;">​</a></h2><p>Under sustained load (100 connections, 60+ seconds), the server&#39;s RSS must not grow. Measured with <code>scripts/performance/long_run_memory.sh</code>.</p><h2 id="optimization-features" tabindex="-1">Optimization Features <a class="header-anchor" href="#optimization-features" aria-label="Permalink to &quot;Optimization Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th><th>Impact</th></tr></thead><tbody><tr><td>Keep-Alive connection reuse</td><td>Active</td><td>~1000x vs per-request</td></tr><tr><td>O(1) route lookup (trie)</td><td>Active</td><td>Eliminates linear scan</td></tr><tr><td>LRU cache for static files</td><td>Active</td><td>Reduces disk I/O</td></tr><tr><td>Zero-copy sendfile</td><td>Active</td><td>50%+ CPU reduction for large files</td></tr><tr><td>Direct libuv calls</td><td>Design</td><td>No abstraction layer</td></tr><tr><td>Compile-time feature selection</td><td>Active</td><td>No runtime overhead for unused features</td></tr></tbody></table><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Performance regression test on every PR (via CI)</li><li>Benchmark results must be reproducible</li><li>Historical baseline stored in <code>docs/performance/baseline-history.json</code></li><li>RPS degradation &gt; 5% from baseline must be investigated</li></ul>',17)])])}const b=e(o,[["render",n]]);export{m as __pageData,b as default};
